with open("data/solutions/chunks/aptitude/batches_parajumble/input_batch_04.json", "r", encoding="utf-8") as f:
    items = json.load(f)

all_passed = True
for item in items:
    uid = item["uid"]
    ans = item["answer"]
    exp = item["expected_sequence"].replace("\\n", "").replace("\\r", "").strip()
    sol = solutions.get(uid)
    if not sol:
        print("MISSING UID:", uid)
        all_passed = False
        continue
    expected_conclusion = f"Hence, the correct logical order is **{exp}** (**Option {ans}**)."
    if expected_conclusion not in sol:
        print(f"MISMATCH in conclusion for {uid}:")
        print("Expected:", expected_conclusion)
        print("Got:", sol.strip().splitlines()[-1])
        all_passed = False

if all_passed:
    print("ALL 20 SOLUTIONS VALIDATED PERFECTLY!")
    with open("data/solutions/chunks/aptitude/batches_parajumble/output_batch_04.json", "w", encoding="utf-8") as f:
        json.dump(solutions, f, indent=2, ensure_ascii=False)
    print("Saved output_batch_04.json successfully!")
